{
  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret nævner ikke minimumskravet om journalmateriale fra egen læge, speciallæge, hospital eller ambulant klinik (§ 37, stk. 3). Det tilføjer krav, som ikke findes i kilderne: en aktuel lægelig vurdering med prognose er anført som noget, der skal vedlægges, og dokumentationen skal beskrive hvorfor et studiejob er vanskeligt eller umuligt. Det siger også, at en kort erklæring fra egen læge kan være utilstrækkelig, og at SU ikke nødvendigvis kræver ét bestemt dokument. Epikrisen nævnes først og ikke som et 'som udgangspunkt'-element. Der er flere væsentlige mangler og tilføjelser."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Af de tre kritiske elementer er kun delvis dækning til stede. Journalmateriale fra de nævnte kildetyper som minimumskrav mangler: svaret nævner kun 'journalnotater' generelt og 'aktuel lægelig vurdering'. Kravet om beskrivelse af den varige funktionsnedsættelse er kun indirekte dækket ('funktionsnedsættelsen forventes at være varig'). Epikrise/afslutningsbrev nævnes, men uden 'som udgangspunkt' ved afsluttet behandling."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken lægelig dokumentation der bør vedlægges, når behandlingen er afsluttet, og afviger ikke til irrelevant stof."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde (hverken bestemmelse, lov eller vejledning). Der henvises kun generelt til 'SU'."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer indhold uden støtte i materialet: aktuel lægelig vurdering med prognose og behandlingsresultat som dokumentationselement, beskrivelse af hvorfor et studiejob er vanskeligt eller umuligt, udsagn om at en kort erklæring fra egen læge kan være utilstrækkelig, og at en egen beskrivelse kan vedlægges. Kilderne nævner aktualitet og art/grad (§ 37, stk. 4), men ikke disse konkrete krav."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Forbeholdet 'som udgangspunkt' for epikrise/afslutningsbrev bevares ikke; epikrisen står som første punkt i en liste over, hvad der skal vedlægges. Svaret siger heller ikke, at titlen ikke afgør tilstrækkeligheden. Svaret opstiller i øvrigt ikke minimumskravet om journaler fra én af de nævnte kilder."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: dokumentationen skal vise tilstand, forløb og nuværende påvirkning, og de anførte dokumenter understøtter dette. Der er ingen indre modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'bør', 'så vidt muligt' og 'normalt' om krav, som kilden formulerer som 'skal' (journalminimum) eller 'som udgangspunkt' (epikrise). Det gør minimumskravet blødt og stiller anbefalinger op som krav, hvilket forvansker modaliteten."
    }
  },
  "xhaile_coverage": {
    "A30": {
      "label": "partial",
      "reason": "Svaret nævner epikrise eller afsluttende journalnotat efter afsluttet behandling, men angiver ikke, at det kun er et udgangspunkt, og uden kildehenvisning."
    },
    "A32": {
      "label": "partial",
      "reason": "Epikrise/afsluttende journalnotat er med som dokument, men uden den præcise 'som udgangspunkt'-modalitet og uden at koble det til minimumskravet om journaler."
    }
  },
  "overall_notes": "Svaret er relevant og sammenhængende, men det udelader minimumskravet om journalmateriale fra de nævnte kilder og beskrivelsen af den varige funktionsnedsættelse, det mister 'som udgangspunkt'-forbeholdet og tilføjer ustøttede krav. Det angiver ingen kilder, så C04 er not_met og C05/C06 not_assessable."
}

